INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_JCBC','KUL MOCKS New Flavor Alert Email','Email from KUL MOCKS discussing new mocktail flavors and seeking brand ambassadors in Wisconsin, relevant for lead generation and business development.','email','Looking for Wisconsin Ambassadors, details inside! Fall and winter call for something a little festive and a little cozy! We’ve been busy behind the scenes, dreaming up and crafting mocktails that taste like the season—recipes built with the same care and creativity we’d put into mixing one for friends around our own table. In just a few days, we’ll drop three new flavors designed for crisp nights, holiday gatherings, and every toast in between. Think of them as your secret weapon when the party needs something different—or when you’d rather keep the night clear but still feel part of the toast. And yes, they’ll look as good on your bar cart as they taste in your glass. These cans were made for showing off. The lineup is still under wraps, but let’s just say: you’ll want these stocked before the parties start. Flavor reveals land next week—and we can’t wait for you to try them! Make sure to tune in on IG for the latest! Shop NOW on AMAZON! MILWAUKEE & MADISON AMBASSADORS WANTED We’re looking for YOU, Milwaukee + Madison, Wisconsin! KUL MOCKS is looking for energetic Brand Ambassadors to help share our craft mocktails at our local retail partners. If you enjoy connecting with people, offering samples, and spreading good vibes, we’d love to have you on the KUL KREW. Click here to learn more. COMING UP! FASHIONOPOLIS EVENT! Come party with us at the 13th annual Fashionopolis event in Minneapolis MN September 26! Brought to you by Mpls.St.Paul Magazine; this black and white experience will not disappoint! Shop NOW on AMAZON! BUY IN-STORESHOP ONLINEOUR STORYPRESSGet social with us! Visit kulmocks.com','["business", "lead_generation", "business_development"]','{"timestamp": "2025-10-19T08:44:34.768608+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.007100651,-0.035381064,-0.0011956043,-0.025076294,-0.0010437142,0.044015888,-0.022564592,-0.004103579,-0.004497305,-0.026814122,0.02131553,-0.003311035,-0.02299905,-0.032692865,-0.019998582,-0.013712538,0.026827699,-0.03787919,0.002605043,0.00093764573,-0.013230563,0.018070681,0.031498108,0.022062251,-0.020948958,0.0056479364,0.01618351,-0.010474479,-0.022320211,0.012796106,0.020378733,0.007827008,-0.016835196,-0.00275269,-0.010718861,-0.010657765,0.0033958897,-0.006469331,0.013929767,0.0016512747,-0.010949666,0.0037743421,0.014513568,-0.03665728,-0.016631544,0.029325824,-0.009897466,-0.00845154,0.007854162,0.034104846,0.029108595,0.0033619478,-0.011173682,0.017378267,0.012144421,-0.017839877,-0.007487589,0.014350646,-0.0027866322,0.0050301934,-0.0006771414,0.021641372,-0.01971347,0.010589881,-0.006465937,0.0037573713,-0.04292975,-0.015966281,0.0113909105,-0.019577703,0.019944277,0.022075828,0.009449433,-0.010250461,0.010060387,0.0037641595,-0.015939128,-0.010569516,-0.010841051,0.0070259785,0.012639973,-0.033018705,-0.028674139,0.04211514,0.000828183,0.044151656,-0.009211839,0.0035028069,-0.012171575,0.014798679,-0.013766846,0.009483374,-0.0020025736,0.013461368,-0.034783687,-0.0012923388,-0.014907294,0.039019637,0.0077591245,-0.02976028,-0.0074468586,0.020378733,-0.015884822,-0.014119841,-0.043825816,0.016740158,-0.004914791,-0.029461592,0.023066932,-0.00032096333,-0.031851105,0.019998582,0.003703064,-0.014309916,-0.031633876,-0.015110945,0.0038524086,0.011010