INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_PZDC','Automated MDB Daily Report','Email regarding the setup of an Automated MDB Daily Report with instructions to send daily to Million Dollar Baby recipients. The email includes a request from Katie McDonnell, Strategic Account Manager, to set up the report for daily dispatch from Seabrook, 300 Pooler. The email is marked as high importance and includes an attachment as an example of the report.','email','Report attached as example. Thanks Katie McDonnellStrategic Account ManagerCell: 630-341-3043 From: Katie McDonnell Sent: Tuesday, September 23, 2025 11:19 AMTo: Wise Support <WISEsupport@unisco.com>Cc: Dan Linnihan <dan.linnihan@unisco.com>Subject: Automated MDB Daily ReportImportance: High Good Morning, Can we set this report up attached to send daily to Million Dollar Baby recipients out of Seabrook, 300 Pooler? Let me know if anything else is needed, and then I will send over who it should go to, thanks! Katie McDonnellStrategic Account Manager Unis Transportation630.341.30431333 N Kingsbury St, Chicago IL 60642Katie.mcdonnell@unisco.com |www.unisco.com','["industry_reports", "thought_leadership", "executive_insights"]','{"timestamp": "2025-10-19T08:27:30.822524+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.043869995,-0.015803395,-0.002216157,-0.03375922,-0.024342325,0.03310783,-0.014344837,-0.006478542,-0.020717174,-0.0053032,0.009459379,0.02177923,0.012022475,0.026423955,-0.0027365645,0.019640956,0.010167416,-0.004018112,0.0042