INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_NZ1B','New Flavor Alert Email from KUL MOCKS','Email received from KUL MOCKS regarding new mocktail flavors and ambassador opportunities in Wisconsin, relevant for lead generation and business development.','email','Looking for Wisconsin Ambassadors, details inside! Fall and winter call for something a little festive and a little cozy! We’ve been busy behind the scenes, dreaming up and crafting mocktails that taste like the season—recipes built with the same care and creativity we’d put into mixing one for friends around our own table. In just a few days, we’ll drop three new flavors designed for crisp nights, holiday gatherings, and every toast in between. Think of them as your secret weapon when the party needs something different—or when you’d rather keep the night clear but still feel part of the toast. And yes, they’ll look as good on your bar cart as they taste in your glass. These cans were made for showing off. The lineup is still under wraps, but let’s just say: you’ll want these stocked before the parties start. Flavor reveals land next week—and we can’t wait for you to try them! Make sure to tune in on IG for the latest! Shop NOW on AMAZON! MILWAUKEE & MADISON AMBASSADORS WANTED We’re looking for YOU, Milwaukee + Madison, Wisconsin! KUL MOCKS is looking for energetic Brand Ambassadors to help share our craft mocktails at our local retail partners. If you enjoy connecting with people, offering samples, and spreading good vibes, we’d love to have you on the KUL KREW. Click here to learn more. COMING UP! FASHIONOPOLIS EVENT! Come party with us at the 13th annual Fashionopolis event in Minneapolis MN September 26! Brought to you by Mpls.St.Paul Magazine; this black and white experience will not disappoint! Shop NOW on AMAZON! BUY IN-STORE SHOP ONLINE OUR STORY PRESS Get social with us! Visit kulmocks.com This email was sent from this site. If you no longer wish to receive this email, change your email preferences here.','["business", "lead_generation", "business_development"]','{"timestamp": "2025-10-19T08:43:41.284560+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.010301932,-0.03970678,-0.0019921616,-0.027671944,-0.0076752803,0.044400644,-0.01893918,-0.012717087,-0.012198579,-0.026430253,0.027289886,-0.0019256425,-0.027617363,-0.036322836,-0.024233418,-0.012935406,0.026566703,-0.042626802,0.004441429,-1.8255441e-05,-0.0057683997,0.02123153,0.032529544,0.018488897,-0.025543332,0.004287923,0.018980116,-0.010902309,-0.021327045,0.006716723,0.019880682,0.010117725,-0.02045377,0.002879083,-0.0100495005,-0.007020323,-0.0026266514,-0.008050516,0.0075934106,0.0028824941,-0.0066348533,0.0066416757,0.018175064,-0.03768733,-0.018243289,0.026730442,-0.012826246,-0.014136161,0.005628539,0.03596807,0.03151982,-0.002544782,-0.010922777,0.008064161,0.013754102,-0.02048106,-0.010458848,0.011475396,-0.007395559,0.0125397025,0.0010856257,0.015104951,-0.016660474,0.01071128,-0.0029336626,0.0063312533,-0.041344177,-0.017793005,0.0034299975,-0.0107249245,0.021217886,0.02139527,0.012519235,-0.012055307,0.0076548127,0.0028841998,-0.015064017,-0.0073341564,-0.012082596,0.002865438,0.0073205116,-0.040661927,-0.029636815,0.039815944,0.0004698977,0.045901585,-0.012048485,0.00086901226,-0.015855424,0.005440921,-0.010138192,0.015732618,-0.004867833,0.008725941,-0.032420382,-0.0015828133,-0.018475253,0.04508289,0.010056322,-0.033839457,-0.01371999,0.02379678,-0.00888968,-0.016892439,-0.046229064,0.015937293,-0.0017874875,