INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_VSNN','Unisco EDI940 / EDI945 / ASN856 3PL Testing Email','Email conversation about EDI940, EDI945, ASN856 3PL testing involving multiple stakeholders, focusing on testing scenarios and requirements, and discussion on adding functionality to monitor connection status due to disruptions. The development team will take time to schedule the work, and a holiday from October 1st to October 8th will affect the timeline.','email','Hi @Michael Deller@Mark Golding,I’ve discussed this with our BA, and they’ve confirmed that a new functionality will be added to monitor the connection status — whether it’s interrupted due to manual configuration changes or unexpected disruptions. However, please note that our development team will need some time to schedule the work, and we also have an upcoming 8-day holiday from October 1st to October 8th. As a result, this functionality is expected to be released approximately a month from now. Thanks for your understanding! Best Regards, Juan Dai (Livia) Beijing, China IT Implementation/EDI Engineer Email: livia.dai@item.com','["work", "notifications_hr_organizational_matters"]','{"timestamp": "2025-10-19T09:57:55.635533+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.022111949,-0.020420706,-0.0016947369,-0.008029908,-0.034048487,0.019568095,-0.038353465,0.012013413,-0.011216712,-0.019498209,0.006890765,0.011573131,0.007352013,-0.011090917,-0.011859664,-0.0058110254,0.008896495,-0.017513445,0.0113494955,-0.0013068