INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_MK8T','Betesh Mapping for ODC2','Email discussion on the synchronization of production and test environments for EDI mapping, highlighting issues with missing PO#/REL/DESK/COST information in the EDI_940 message, affecting the packing list''s completeness. It includes communication between Eaden Wu, Jennifer Kuo, and others regarding mapping configurations and necessary updates.','email','Hi @Jennifer Kuo - Unisco,After review, the configurations for the production and test environments are now synchronized. Please find the latest mapping document attached.For the production order: PROD/Cesanek/DN-1110805Since the customer’s transmitted EDI_940 message is missing the PO#/REL/DESK/COST information, the Packing List cannot display the full details. Please remind the customer to update the EDI_940 and include the PO#/REL/DESK/COST information.For the test order: Stage/Cesanek/DN-453352The order information is complete, and the currently generated Packing List meets expectations. Please reach out to the customer for confirmation.Best Regards，Zhiqiang Wu(Eaden)Peking, CNSenior EDI engineerM +86 15083820695zhiqiang.wu@item.com','["work", "internal_communication", "project_updates"]','{"timestamp": "2025-10-19T13:44:31.273023+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[0.0006363506,-0.0150812445,0.006018337,-0.011980031,-0.026353234,0.02160937,-0.019754305,0.013997943,-0.009940877,-0.02768435,-0.0071901423,0.005462526,0.013672246,0.011951709,-0.