INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_B1UN','Urgent Shelf Life Rule Review Email','Email regarding urgent review of shelf life rules for the B2B program in Wise. Involves participants from Unisco and UpSnack Brands Inc. Highlights issues with current rules allowing items with less than 135 days of shelf life to be picked for orders.','email','Please advise on this asapWSP-93400  Dan LinnihanDirector Account ManagementPhone: 773.351.2709Email: dan.linnihan@unisco.com Website: www.unisco.com  From: Kyle Merical <kyle@upsnackbrands.com> Sent: Monday, September 15, 2025 2:37 PMTo: upsnack.joliet@unisco.com; Yesenia Diaz <yesenia.diaz@unisco.com>; Francine Franco <francine.franco@unisco.com>; Timothy Nitka <timothy.nitka@unisco.com>; Dan Linnihan <dan.linnihan@unisco.com>; Mike Chordas <mchordas@factory-llc.com>; Cara Gao <cara.gao@item.com>; Jennifer Kuo <jennifer.kuo@unisco.com>Subject: **Urgent** Shelf Life Rule Review Hello Team,We need an immediate review of shelf life rules for our B2B program in Wise.Items with <135 days are being picked onto orders (example below). This was flagged on Friday’s Teams chat, but with Francine out, no one has followed up. Please do not waste time fixing this DN, it’s only an example to show where the rule is failing.Reminder of Rules:For B2B, Wise should not allow any Lots below 135 days of remaining shelf life.For Drop Ship, Wise should allow down to 60 days to support small parcel orders.We have not requested any changes to these rules. This needs attention immediately as it points to a broader Wise issue.Best,Kyle  OrderNoStatusItemIDLot CodeDN-1721133PickedSPPOSV4C92026-01-11    Kyle MericalSupply Chain Manager UpSnack Brands Inc. - Pipsnacks & SpudsyCell:  (562) 450-03421 East Broad Street, Suite 210Bethlehem, PA 18018','["IT Support & Platform Upgrade"]','{"timestamp": "2025-10-19T14:34:21.365172+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.01101091,-0.03460974,-0.0034708304,-0.011109473,-0.02293705,-0.004023488,-0.011560048,-0.004942237,-0.008532751,-0.016797975,0.014291654,-0.0073218327,-0.014545103,-0.013122978,0.0007880651,0.018262342,0.012123265,2.579582e-05,0.025710898,-0.0018814998,-0.004811993,-0.009398699,-0.011053151,-0.002671765,0.010595537,-0.018910041,0.0113066,-0.02072642,0.009595825,-0.0068782987,0.02928733,-0.009701429,-0.013862201,0.014868953,-0.003710198,-0.016966939,0.005755383,-0.015164643,0.032610316,-0.024964634,0.010257606,0.028583309,0.017121825,0.013017374,-0.00627636,0.015488492,0.0050126393,-0.0074626375,-0.0156997,0.018811477,0.013496109,-0.013960764,-0.04080514,-8.057756e-05,0.018262342,-0.0019272612,0.004811993,0.028710034,-0.014207172,0.0106941005,0.0029744946,-0.010637778,-0.025035037,-0.0018304582,0.005565297,-0.011905018,-0.043536745,-0.002955134,0.010736342,-0.0059595495,0.02361291,0.032694798,0.006638931,0.00880028,0.024936473,-0.0075330394,-0.012362633,0.010328009,0.018065214,0.0026999258,0.007357034,-0.023021532,-0.023176417,0.013376425,0.012475276,0.0039706863,-0.019022685,0.0053329696,-0.016966939,-0.0009768311,-0.00409037,0.011778294,0.005600498,0.018515788,-0.019628145,0.013636914,-0.005882107,0.041621804,-0.0023989563,-0.02452814,0.0034813907,0.0069311005,-0.012489357,-0.0048507145,-0.023514347,0.009300136,-0.016122112,-0.011489646,-0.0032613836,-0.0075330394,-0.03238503,0.03244135,0.009208613,-0.024584461,-0.0027703282,0.01037729,0.017501997,-0.016840216,-0.0066494914,-0.031878132,0.018065214,-0.0136650745,0.019459179,-0.032948248,0.027639918,0.00842714