INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_P0CC','Trello Account Authorization Email','Email received from Trello indicating a new app ''Email Assist'' was authorized on the user''s account. It details what the app can and cannot do, emphasizing security and access rights within Trello. Categorized under Internal Business Communication.','email','您好！我们注意到您已授权您的 Trello 帐户中的新应用。应用：Email Assist已添加日期和时间：September 13, 2025 8:20 AM UTC如果这是您，请忽略此电子邮件。如果您没有授权此应用，请在您 Trello 帐户页面的“应用”部分撤销其对您帐户的访问权限。Email Assist 将能够：读取你的名字和用户名在你完成以下各项时留下评论：读取你的邮件地址解读你的企业升级和管理你的企业读取所有面板和工作区创建和更新卡片、列表、面板以及工作区读取你拥有的 Power-Ups更新你拥有的 Power-UpsEmail Assist 将不能：查看你的Trello密码Email Assist 将有权访问您账号下的所有面板，包括其他工作区上的面板。此外，Email Assist 将有权访问您将来获得访问权限的所有面板和工作区。如果您认为您的帐户遭到入侵，并需详细了解应对方法，请阅读我们的支持文档。谢谢！Trello 支持','["work", "Internal Business Communication"]','{"timestamp": "2025-10-19T16:31:36.044571+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.029243838,-0.0144605,-0.005777474,-0.035431586,-0.012994273,0.0051418846,-0.035162553,-0.031369194,-0.0039984966,-0.028033193,0.0124024,-0.045170568,0.0036554798,-0.01801173,-0.026176868,0.011844158,0.02288122,-0.00054731313,0.0032906043,0.003763093,-0.015348307,0.002851745,-0.026042351,0.011259013,-0.012415852,-0.0260289,0.0039547784,-0.015052372,0.006648467,-0.004587005,0.03231081,0.025477383,-0.013660128,-0.014635371,-0.011205206,-0.020379215,0.017339148,-0.011884513,0.024764447,0.019989118,0.020567538,0.023499994,-0.01111777,-0.0013300297,-0.0036891089,0.032579843,0.013855177,-0.01