INSERT INTO public.resource_memory (id, title, summary, resource_type, content, tree_path, last_modify, metadata_, embedding_config, summary_embedding, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id, organization_id, user_id) VALUES ('res_KG5H','Second attempt - Meeting proposal from Dan D''Amato','Dan D''Amato from Oracle proposed a meeting with Shelia Sun to discuss system consolidation for accounting, inventory, CRM, warehouse, and shop floor systems. The email was categorized under Lead Generation and Business Development.','email','I sent the note below a couple days ago and wanted to check back with this trip coming up. Would you be open to getting together because I don''t get that way very often? I wanted to reach out about a meeting that I think might be beneficial for both sides. I am headed that way to visit a customer of ours and I think it would be a good opportunity for us to dive into what systems you are using for accounting, inventory, CRM, warehouse, shop floor, etc. We may be able to help consolidate things into one system depending on your current setup and needs. Would you like to get together while I am nearby? Dan D''Amato | Senior Regional Sales Director 240.532.2794 dan.damato@oracle.com Unsubscribe.','["Lead Generation", "Business Development"]','{"timestamp": "2025-10-19T18:16:08.300794+00:00", "operation": "created"}','{}','{"embedding_endpoint_type": "openai", "embedding_endpoint": "https://api.openai.com/v1", "embedding_model": "text-embedding-3-small", "embedding_dim": 1536, "embedding_chunk_size": 8191, "handle": null, "azure_endpoint": null, "azure_version": null, "azure_deployment": null}','[-0.0012758028,-0.025918046,-0.0082578,-0.018464223,-0.0074878894,0.020399218,-0.005270139,0.004183407,-0.0020627466,-0.03406683,0.024419105,0.025890792,0.032131836,0.01568437,0.00414934,0.014321696,0.013299691,-0.003207392,-0.002801997,-0.020222072,-0.03703746,-0.0064454447,-0.00026934088,0.025550123,0.0123867,-0.0134087